package mrpapermoon.whisper.actorsimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.SupervisorJobimport kotlinx.coroutines.channels.Channelimport kotlinx.coroutines.flow.Flowimport kotlinx.coroutines.flow.FlowCollectorimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.emitAllimport kotlinx.coroutines.launchimport mrpapermoon.whisper.mesh.MeshNetworkManagerimport javax.inject.Injectimport javax.inject.Singletonsealed interface MeshAction {	data object Initialize : MeshAction	data class Whisper(val message: String) : MeshAction}sealed interface MeshState {	data object Idle : MeshState	data object Initializing : MeshState	data object Ready : MeshState	data class Error(val errorMessage: String) : MeshState}@Singletonclass MeshActor @Inject constructor(	private val meshNetworkManager: MeshNetworkManager,) : Flow<MeshState> {	private val actions = Channel<MeshAction>(Channel.UNLIMITED)	private val scope = CoroutineScope(Dispatchers.Default + SupervisorJob())	private val state = MutableStateFlow<MeshState>(MeshState.Idle)	init {		scope.launch {			for (action in actions) {				when (action) {					is MeshAction.Initialize -> {						startService()					}					is MeshAction.Whisper -> {						// Handle whisper message action					}				}			}		}	}	override suspend fun collect(collector: FlowCollector<MeshState>) {		collector.emitAll(state)	}	fun send(action: MeshAction) {		actions.trySend(action)	}	private suspend fun startService() {		if (state.value is MeshState.Ready) return		state.value = MeshState.Initializing		runCatching {			meshNetworkManager.startService()		}			.onSuccess {				state.value = MeshState.Ready			}			.onFailure { throwable ->				state.value = MeshState.Error(throwable.message ?: "Failed to initialize MeshNetworkManager")				throw throwable			}	}}